+<body>
+  <main class="support-shell">
+    <section class="support-copy" aria-labelledby="support-heading">
+      <p class="eyebrow">Support</p>
+      <h1 id="support-heading">Talk to our team about anything you need.</h1>
+      <p>
+        Send a quick request and we will reach out with help, product guidance, or next steps for your account.
+      </p>
+      <ul class="highlights" aria-label="Support benefits">
+        <li>Fast response</li>
+        <li>Product specialists</li>
+        <li>Friendly follow-up</li>
+      </ul>
+    </section>
+
+    <section class="support-card" aria-labelledby="contact-form-heading">
+      <h2 id="contact-form-heading">Contact support</h2>
+      <p>Fill out the form below and we will get back to you as soon as we can.</p>
+
+      <form id="support-form" novalidate>
+        <div class="form-field">
+          <label for="full-name">Full name</label>
+          <input
+            id="full-name"
+            name="fullName"
+            type="text"
+            autocomplete="name"
+            placeholder="Jordan Lee"
+            required
+            aria-describedby="full-name-message"
+          >
+          <p class="field-message" id="full-name-message" aria-live="polite"></p>
+        </div>
+
+        <div class="form-field">
+          <label for="email-address">Email address</label>
+          <input
+            id="email-address"
+            name="email"
+            type="email"
+            autocomplete="email"
+            placeholder="jordan@example.com"
+            required
+            aria-describedby="email-address-message"
+          >
+          <p class="field-message" id="email-address-message" aria-live="polite"></p>
+        </div>
+
+        <div class="form-field">
+          <label for="phone-number">Phone number</label>
+          <input
+            id="phone-number"
+            name="phone"
+            type="tel"
+            autocomplete="tel"
+            inputmode="tel"
+            placeholder="(555) 123-4567"
+            aria-describedby="phone-number-helper phone-number-message"
+          >
+          <p class="helper-text" id="phone-number-helper">Optional. Use a format like (555) 123-4567 or +1 555 123 4567.</p>
+          <p class="field-message" id="phone-number-message" aria-live="polite"></p>
+        </div>
+
+        <button class="submit-button" type="submit">Submit</button>
+        <p class="form-status" id="form-status" aria-live="polite"></p>
+      </form>
+    </section>
+  </main>
+
+  <script>
+    const form = document.getElementById("support-form");
+    const formStatus = document.getElementById("form-status");
+
+    const fields = [
+      {
+        input: document.getElementById("full-name"),
+        message: document.getElementById("full-name-message"),
+        validate(value) {
+          return value.trim() ? "" : "Enter your full name.";
+        }
+      },
+      {
+        input: document.getElementById("email-address"),
+        message: document.getElementById("email-address-message"),
+        validate(value) {
+          if (!value.trim()) {
+            return "Enter your email address.";
+          }
+
+          return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value) ? "" : "Enter a valid email address.";
+        }
+      },
+      {
+        input: document.getElementById("phone-number"),
+        message: document.getElementById("phone-number-message"),
+        validate(value) {
+          if (!value.trim()) {
+            return "";
+          }
+
+          return /^[+]?[0-9()\s-]{7,20}$/.test(value)
+            ? ""
+            : "Use a valid phone number format.";
+        }
+      }
+    ];
+
+    const setFieldState = ({ input, message }, error) => {
+      const field = input.closest(".form-field");
+      message.textContent = error;
+
+      if (error) {
+        field.classList.add("invalid");
+        input.setAttribute("aria-invalid", "true");
+      } else {
+        field.classList.remove("invalid");
+        input.removeAttribute("aria-invalid");
+      }
+    };
+
+    const validateField = (fieldConfig) => {
+      const error = fieldConfig.validate(fieldConfig.input.value);
+      setFieldState(fieldConfig, error);
+      return !error;
+    };
+
+    fields.forEach((fieldConfig) => {
+      fieldConfig.input.addEventListener("blur", () => {
+        validateField(fieldConfig);
+      });
+
+      fieldConfig.input.addEventListener("input", () => {
+        if (fieldConfig.message.textContent) {
+          validateField(fieldConfig);
+        }
+
+        if (formStatus.textContent) {
+          formStatus.textContent = "";
+        }
+      });
+    });
+
+    form.addEventListener("submit", (event) => {
+      event.preventDefault();
+
+      const isValid = fields.every((fieldConfig) => validateField(fieldConfig));
+
+      if (!isValid) {
+        formStatus.textContent = "Please correct the highlighted fields before submitting.";
+        return;
+      }
+
+      formStatus.textContent = "Thanks! Your support request is ready to be sent.";
+      form.reset();
+      fields.forEach((fieldConfig) => setFieldState(fieldConfig, ""));
+    });
+  </script>
+</body>
+</html>
